from pathlib import Path

p = Path('pdf-loader-project/app/src/main/java/com/pdfloader/app/MainActivity.java')
s = p.read_text()

s = s.replace('import android.content.ContentResolver;\n', 'import android.content.ContentResolver;\nimport android.content.ContentValues;\n')
s = s.replace('import android.os.Bundle;\n', 'import android.os.Bundle;\nimport android.os.Environment;\n')
s = s.replace('import android.provider.DocumentsContract;\n', 'import android.provider.DocumentsContract;\nimport android.provider.MediaStore;\n')
s = s.replace('    private static final int PICK_PDF_TO_IMAGES = 30;\n    private static final int PICK_OUTPUT_TREE = 31;\n', '    private static final int PICK_PDF_TO_IMAGES = 30;\n')
s = s.replace('body.addView(sheetAction("image", "PDF → Images", v -> { d.dismiss(); pendingPdfForImages = currentPdf; pickOutputTree(); }));', 'body.addView(sheetAction("image", "PDF → Images", v -> { d.dismiss(); exportPdfPagesToGalleryAsync(currentPdf); }));')
s = s.replace('''    private void pickOutputTree() {\n        Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);\n        startActivityForResult(i, PICK_OUTPUT_TREE);\n    }\n\n''', '')
s = s.replace('''            else if (requestCode == PICK_PDF_TO_IMAGES) { pendingPdfForImages = data.getData(); pickOutputTree(); }\n            else if (requestCode == PICK_OUTPUT_TREE) exportPdfPagesToImages(pendingPdfForImages, data.getData());''', '''            else if (requestCode == PICK_PDF_TO_IMAGES) {\n                pendingPdfForImages = data.getData();\n                exportPdfPagesToGalleryAsync(pendingPdfForImages);\n            }''')

old = '''    private void exportPdfPagesToImages(Uri pdf, Uri tree) throws IOException {\n        if (pdf == null || tree == null) return;\n        ContentResolver cr = getContentResolver();\n        try (ParcelFileDescriptor fd = cr.openFileDescriptor(pdf, "r"); PdfRenderer r = new PdfRenderer(fd)) {\n            for (int i = 0; i < r.getPageCount(); i++) {\n                try (PdfRenderer.Page p = r.openPage(i)) {\n                    int w = Math.max(1200, p.getWidth() * 2);\n                    int h = Math.max(1, (int) (w * (p.getHeight() / (float) p.getWidth())));\n                    Bitmap b = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);\n                    b.eraseColor(Color.WHITE);\n                    p.render(b, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);\n                    Uri out = DocumentsContract.createDocument(cr, tree, "image/png", String.format(Locale.ROOT, "page-%03d.png", i + 1));\n                    if (out != null) try (OutputStream os = cr.openOutputStream(out)) { b.compress(Bitmap.CompressFormat.PNG, 100, os); }\n                    b.recycle();\n                }\n            }\n        }\n        Toast.makeText(this, "Pages exportées en PNG.", Toast.LENGTH_LONG).show();\n    }\n'''

new = '''    private void exportPdfPagesToGalleryAsync(Uri pdf) {\n        if (pdf == null) return;\n        Toast.makeText(this, "Export vers la galerie…", Toast.LENGTH_SHORT).show();\n        new Thread(() -> {\n            try {\n                int count = exportPdfPagesToGallery(pdf);\n                runOnUiThread(() -> Toast.makeText(this, count + (count > 1 ? " images enregistrées" : " image enregistrée") + " dans Pictures/Pdf Loader.", Toast.LENGTH_LONG).show());\n            } catch (Exception e) {\n                runOnUiThread(() -> Toast.makeText(this, "Erreur export : " + e.getMessage(), Toast.LENGTH_LONG).show());\n            }\n        }, "PdfLoaderGalleryExport").start();\n    }\n\n    private int exportPdfPagesToGallery(Uri pdf) throws IOException {\n        ContentResolver cr = getContentResolver();\n        String base = displayName(pdf);\n        if (base.toLowerCase(Locale.ROOT).endsWith(".pdf")) base = base.substring(0, base.length() - 4);\n        base = base.replaceAll("[\\\\/:*?\\\"<>|]", "-").trim();\n        if (base.isEmpty()) base = "PDF";\n        String folder = Environment.DIRECTORY_PICTURES + "/Pdf Loader/" + base;\n        int exported = 0;\n        ParcelFileDescriptor fd = cr.openFileDescriptor(pdf, "r");\n        if (fd == null) throw new IOException("PDF inaccessible");\n        try (ParcelFileDescriptor closableFd = fd; PdfRenderer r = new PdfRenderer(closableFd)) {\n            for (int i = 0; i < r.getPageCount(); i++) {\n                try (PdfRenderer.Page page = r.openPage(i)) {\n                    int w = Math.max(1800, page.getWidth() * 3);\n                    int h = Math.max(1, Math.round(w * (page.getHeight() / (float) page.getWidth())));\n                    Bitmap bitmap = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);\n                    bitmap.eraseColor(Color.WHITE);\n                    page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_PRINT);\n                    String name = String.format(Locale.ROOT, "%s-page-%03d.png", base, i + 1);\n                    ContentValues values = new ContentValues();\n                    values.put(MediaStore.Images.Media.DISPLAY_NAME, name);\n                    values.put(MediaStore.Images.Media.MIME_TYPE, "image/png");\n                    values.put(MediaStore.Images.Media.RELATIVE_PATH, folder);\n                    values.put(MediaStore.Images.Media.IS_PENDING, 1);\n                    Uri out = cr.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values);\n                    if (out == null) { bitmap.recycle(); throw new IOException("Impossible de créer l’image " + (i + 1)); }\n                    boolean ok;\n                    try (OutputStream os = cr.openOutputStream(out, "w")) {\n                        if (os == null) throw new IOException("Stockage inaccessible");\n                        ok = bitmap.compress(Bitmap.CompressFormat.PNG, 100, os);\n                    } finally { bitmap.recycle(); }\n                    if (!ok) { cr.delete(out, null, null); throw new IOException("Échec de l’encodage PNG"); }\n                    ContentValues done = new ContentValues();\n                    done.put(MediaStore.Images.Media.IS_PENDING, 0);\n                    cr.update(out, done, null, null);\n                    exported++;\n                }\n            }\n        }\n        return exported;\n    }\n'''

if old not in s:
    raise SystemExit('export method not found')
s = s.replace(old, new)
p.write_text(s)

b = Path('pdf-loader-project/app/build.gradle')
g = b.read_text().replace('versionCode 4', 'versionCode 5').replace("versionName '0.4.0'", "versionName '0.4.1'")
b.write_text(g)
